((SELECT id FROM seri WHERE slug = 'lainnya'), 'Ngobrol Literasi Sastra Digital Bareng Anak Muda with Ziliun', 'ngobrol-literasi-sastra-digital-bareng-anak-muda-with-ziliun-2jccmu', NULL, '2021-05-31', 3194, 'Belum tercatat', 'Belum tercatat', 'Literasi dan Keluarga', 'literasi_keluarga', 'https://www.youtube.com/watch?v=2JCCmUiXsLQ', '2JCCmUiXsLQ', 'Acara ini terselenggara kerja bareng Ziliun dan Perpustakaan Nasional RI WBS Radio Streaming Perpustakaan Nasional RI', 'tayang'),
((SELECT id FROM seri WHERE slug = 'lainnya'), 'FGD Strategi Komunikasi Digital dalam Layanan Referensi Virtual', 'fgd-strategi-komunikasi-digital-dalam-layanan-referensi-virtual-2hr1nc', NULL, '2022-09-16', 9451, 'Belum tercatat', 'Belum tercatat', 'Layanan Perpustakaan', 'layanan_perpustakaan', 'https://www.youtube.com/watch?v=2hr1NC4IfVg', '2hr1NC4IfVg', 'Perpustakaan Nasional RI sebagai pusat rujukan bagi masyarakat mengemban amanat Undang-Undang untuk memberikan layanan secara prima dengan memanfaatkan kemajuan teknologi informasi dan komunikasi. Salah satu bentuk layanan yang dihadirkan adalah layanan referensi virtual atau Tanya Pustakawan. Moderator : Achmad Riyadi Alberto Materi narasumber 1: Dr. Ulani Yunus, MM. (Akademisi dan Peneliti Bidang Komunikasi) Materi Narasumber 2: Lusiana Monohevita, SS. M.Hum. (Pustakawan Universitas Indonesia)', 'tayang'),
