((SELECT id FROM seri WHERE slug = 'lainnya'), 'Yang Fana Adalah Waktu Kita Abadi - Mengenang Sapardi Djoko Damono', 'yang-fana-adalah-waktu-kita-abadi-mengenang-sapardi-djoko-damono-4u9lmx', NULL, '2020-09-08', 3388, 'Belum tercatat', 'Belum tercatat', 'Sejarah dan Kebudayaan', 'sejarah_kebudayaan', 'https://www.youtube.com/watch?v=4U9lmx_tCY0', '4U9lmx_tCY0', 'Prof. Dr. Sapardi Djoko Damono (lahir di Surakarta, 20 Maret 1940 – meninggal di Tangerang Selatan, 19 Juli 2020 pada umur 80 tahun) adalah seorang pujangga berkebangsaan Indonesia terkemuka. Ia kerap dipanggil dengan singkatan namanya, SDD. Ia dikenal melalui berbagai puisinya mengenai hal-hal sederhana namun penuh makna kehidupan, sehingga beberapa di antaranya sangat populer, baik di kalangan sastrawan maupun khalayak umum WBS Radio Streaming Perpustakaan Nasional RI Perpustakaan Nasional RI Facebook Twitter Instagram', 'tayang'),
