((SELECT id FROM seri WHERE slug = 'lainnya'), 'Isti''datul Maut: Telaah Awal Naskah Syaikhona Kholil Menuju IKON', 'isti-datul-maut-telaah-awal-naskah-syaikhona-kholil-menuju-ikon-9zoaf_', NULL, '2025-06-16', 9686, 'Belum tercatat', 'Belum tercatat', 'Naskah Nusantara', 'naskah_nusantara', 'https://www.youtube.com/watch?v=9ZoAF_9i2Lk', '9ZoAF_9i2Lk', 'DISKUSI NASKAH INGATAN KOLEKTIF NASIONAL Dalam rangka pengusulan naskah kuno "Isti''dadul Maut" asal Jawa Timur ke dalam register Ingatan Kolektif Nasional (IKON). Dinas Perpustakaan dan Kearsipan Provinsi Jawa Timur bekerja sama dengan Perpustakaan Nasional Republik Indonesia dan Masyarakat Pernaskahan Nusantara Menyelenggarakan Kegiatan Diseminasi Naskah Ingatan Kolektif Nasional "Isti''dadul Maut : Telaah Awal Naskah Syaikhona Kholil sebagai Warisan Spiritual Nusantara menuju Ingatan Kolektif Nasional“ Mari mengenal lebih dekat warisan spiritual tersebut melalui: Diskusi Kelompok Terpumpun 📝 Isti''dadul Maut : Telaah Awal Naskah Syaikhona Kholil sebagai Warisan Spiritual Nusantara menuju Ingatan Kolektif Nasional 👤 Narasumber : Abdul M. Cholil Lc., M Ag.– Mudir Mahad Aly Nurul Cholil Bangk', 'tayang'),
