((SELECT id FROM seri WHERE slug = 'lainnya'), 'Naskah Pecenongan Untuk Warga Jakarta: Alih Media sebagai Sarana Pelestarian Pengetahuan dan Sejarah', 'naskah-pecenongan-untuk-warga-jakarta-alih-media-sebagai-sarana-pelestarian-pengetahuan-dan-sejarah-j0grcz', NULL, '2025-06-26', 8540, 'Belum tercatat', 'Belum tercatat', 'Naskah Nusantara', 'naskah_nusantara', 'https://www.youtube.com/watch?v=j0gRcZm9UQc', 'j0gRcZm9UQc', 'Dalam rangka pengusulan Naskah Pecenongan sebagai Ingatan Kolektif Nasional (IKON) Tahun 2025, Dinas Perpustakaan dan Kearsipan Provinsi DKI Jakarta bekerja sama dengan Perpustakaan Nasional Republik Indonesia dan Masyarakat Pernaskahan Nusantara mengundang Anda untuk bersama-sama berpartisipasi dalam upaya pelestarian warisan intelektual Jakarta melalui kegiatan Diseminasi Naskah Ingatan Kolektif Nasional #3 "Naskah Pecenongan Untuk Warga Jakarta: Alih Media sebagai Sarana Pelestarian Pengetahuan dan Sejarah" Detail Kegiatan: Tanggal: Kamis, 26 Juni 2025 Waktu: 09.00 – 12.00 WIB Meeting ID: 972 3290 2077 Passcode: lontara Pembicara: 1. Dr. Dewaki Kramadibrata, M.Hum. (Peneliti, Filolog & Dewan Penasihat Manassa) 2. Dr. Rias Antho Rahmi, M.A. (Filolog, Peneliti & Akademisi Universitas Indo', 'tayang'),
((SELECT id FROM seri WHERE slug = 'lainnya'), 'Menuju 500th Jkt: Warisan Naskah Pecenongan sebagai Cermin Literasi, Budaya, & Identitas Kota Global', 'menuju-500th-jkt-warisan-naskah-pecenongan-sebagai-cermin-literasi-budaya-identitas-kota-global-jdafym', NULL, '2025-06-12', 9403, 'Belum tercatat', 'Belum tercatat', 'Naskah Nusantara', 'naskah_nusantara', 'https://www.youtube.com/watch?v=jdAFYmCwZ_0', 'jdAFYmCwZ_0', 'Perpustakaan Nasional Republik Indonesia bekerja sama dengan Masyarakat Pernaskahan Nusantara dan Dinas Perpustakaan dan Kearsipan Provinsi DKI Jakarta mengundang Anda untuk bersama-sama berpartisipasi dalam upaya pelestarian warisan intelektual Jakarta melalui Kegiatan Diseminasi Naskah Ingatan Kolektif Nasional "Menuju 500 Tahun Jakarta: Warisan Naskah Pecenongan sebagai Cermin Literasi, Budaya, dan Identitas Kota Global" Dihadiri oleh para pakar dan filolog, kegiatan ini akan memfokuskan perhatian pada Naskah Pecenongan. Sebuah warisan tertulis yang merekam dinamika sosial, budaya, dan literasi masyarakat Betawi. Detail Kegiatan: Tanggal: Kamis, 12 Juni 2025 Waktu: 09.00 – 12.00 WIB Zoom ID: 926 3014 4004 Passcode: lontara Link Zoom: Sambutan & Pembukaan oleh: 1. Dr. Nasruddin Djoko Sur', 'tayang'),
