((SELECT id FROM seri WHERE slug = 'lainnya'), 'Siniar "200 Tahun Perang Jawa" #1: Lahirnya Sang Pangeran', 'siniar-200-tahun-perang-jawa-1-lahirnya-sang-pangeran-t1stkl', NULL, '2025-02-03', 3431, 'Belum tercatat', 'Belum tercatat', 'Sejarah dan Kebudayaan', 'sejarah_kebudayaan', 'https://www.youtube.com/watch?v=t1StklaxD9s', 't1StklaxD9s', '“200 Tahun Perang Jawa: #1 Lahirnya Sang Pangeran.” Perang Jawa (1825-1830) merupakan salah satu peristiwa perjuangan paling monumental melawan kolonial dalam sejarah Indonesia. Perang ini memberikan dampak luas baik dari segi sosial, politik, ekonomi, maupun budaya di wilayah Indonesia dan memakan biaya besar bagi Pemerintah Kolonial Belanda. Dalam rangka Festival 200 Tahun Perang Jawa dan upaya pengarus-utamaan naskah kuno Nusantara, Perpustakaan Nasional RI akan mengadakan Siniar Berseri “200 Tahun Perang Jawa” bersama narasumber Prof. Dr. Peter Carey dan moderator Adi Wisnurutomo, S.S. Seri pertama bertajuk "Lahirnya Sang Pangeran." Tahukah #sahabatperpusnas? Lahirnya sang Pangeran ke dunia pada 11 November 1785 telah ditandai oleh peristiwa-peristiawa luar biasa. Menurut penanggalan J', 'tayang'),
